  "role": "pixel-first",
  "issues": [
    {
      "issue_id": "region.2566b9e6fa296f81eac62d51",
      "printed_text": "“the",
      "printed_context": "regarded as “the gross exposure arising from investment transactions executed under the Streamlined Approach”",
      "difference_type": "typographic",
      "finding": "The page prints an opening curly double quotation mark before “the”. The right extraction substitutes a straight single quotation mark. The word is unchanged.",
      "proposed_resolution": "Preserve the printed opening curly double quotation mark.",
      "uncertainty": null
    },
    {
      "issue_id": "region.f391cbeaab8bf926347e9842",
      "printed_text": "Approach”",
      "printed_context": "investment transactions executed under the Streamlined Approach” for the purpose of monitoring compliance with the Streamlining Threshold.",
      "difference_type": "typographic",
      "finding": "The page prints a closing curly double quotation mark after “Approach”. The right extraction substitutes a straight single quotation mark. The word is unchanged.",
      "proposed_resolution": "Preserve the printed closing curly double quotation mark.",
      "uncertainty": null
    },
    {
      "issue_id": "region.75639d9ffcf0282878bb126a",
      "printed_text": [
        {
          "text": "6.",
          "position": "Question number preceding the heading near the top of the page"
        },
        {
          "text": "How should intermediaries monitor compliance with the Streamlining Threshold?",
          "position": "Heading for question 6"
        },
        {
          "text": "Page 3 of 3",
          "position": "Bottom-right footer"
        }
      ],
      "difference_type": "text_omission_and_reading_order",
      "finding": "Both “6.” and “Page 3 of 3” are visibly printed. Their deletion omits source text rather than merely changing typography. The left extraction places the footer before question 6, whereas its printed position is below the page’s body text. The additional supplied locations containing “of” are body-text occurrences; they do not establish that those occurrences were deleted by this token change.",
      "proposed_resolution": "Retain “6.” with its heading. Retain “Page 3 of 3” as a separate footer, following the body in a linear transcription. Do not remove the separately located body-text occurrences of “of” on the basis of this issue.",
      "uncertainty": "The image establishes the printed content and positions, but the supplied token change does not establish an omission of any body-text occurrence of “of”."
    },
    {
      "issue_id": "region.a54c911c5be5d73f447f457e",
      "printed_text": "7.",
      "printed_context": "7. Could intermediaries execute leveraged transactions for and/or provide margin trading to an SPI under the Streamlined Approach?",
      "difference_type": "text_omission",
      "finding": "The question number “7.” is clearly printed to the left of the heading. Its deletion omits a structural identifier; it is not a typographic substitution.",
      "proposed_resolution": "Retain “7.” with the corresponding heading.",
      "uncertainty": null
    }
  ],
  "scope_note": "These findings concern visible source fidelity and reading order. Typographic classification does not determine legal applicability. No superscript, footnote, or table heading is visibly associated with the disputed text."
}
